#include "kstationControllerFirmwareNumberRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <fstream>
#include <memory>
#include <vector>
#include <stdexcept>
struct CPU:H8SEmulator{void history(){lastread=lastwrite=-1;}};
struct Event{uint64_t time;uint32_t addr;uint8_t value;bool write;};
template<class S>struct Tape{S&s;std::array<Event,16>e{};unsigned n=0;uint8_t read(uint32_t a){uint8_t v=a==0xfffff2?0:s.memory[a];if(n<e.size())e[n++]={s.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v){if(n<e.size())e[n++]={s.cycles,a,v,true};s.memory[a]=v;}};
struct A:H8SDevice{Tape<CPU>&t;explicit A(Tape<CPU>&x):t(x){}uint8_t read(uint32_t a)override{return t.read(a);}void write(uint32_t a,uint8_t v)override{t.write(a,v);}};
struct B:kstation::ControllerResourceBus{Tape<kstation::ControllerDeviceState>&t;explicit B(Tape<kstation::ControllerDeviceState>&x):t(x){}bool mapped(uint32_t a)const override{return (a>=0xfffd2c&&a<0xfffe31)||a==0xfffff2;}uint8_t read(uint32_t a)override{return t.read(a);}void write(uint32_t a,uint8_t v)override{t.write(a,v);}};
void check(bool v,const char*s){if(!v)throw std::runtime_error(s);}
int main(int argc,char**argv){try{if(argc!=2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"rom");auto a=std::make_unique<CPU>();auto b=std::make_unique<kstation::ControllerDeviceState>();a->loadmem(rom.data(),rom.size(),0);b->loadMemory(rom.data(),rom.size(),0);b->loadMemory(rom.data(),rom.size(),0x400000);Tape<CPU>x{*a};Tape<kstation::ControllerDeviceState>y{*b};A ab(x);B bb(y);a->memmap(&ab,0xfffd2c,0x105);a->memmap(&ab,0xfffff2,1);b->attachBus(&bb);kstation::ControllerInterruptRuntime irq;kstation::ControllerFirmwareNumberRuntime wait;check(irq.bindVerifiedFirmware(*b,rom.data(),rom.size())&&wait.bindVerifiedFirmware(*b,rom.data(),rom.size()),"bind");uint64_t phases=0,events=0,shorts=0,cases=0;for(unsigned flags=0;flags<256;++flags)for(unsigned v=0;v<128;++v)for(unsigned kind=0;kind<2;++kind){wait.reset();a->cycles=b->cycles=100;a->setSP(0xffff00);a->memory[0xffff00]=0;a->memory[0xffff01]=5;a->memory[0xffff02]=a->memory[0xffff03]=0;a->ccr=uint8_t(flags|0x80);a->exr=0;a->pending_irqs=b->pendingIrqs=(flags&1)?uint64_t(1)<<36:0;a->pending_irqs_high=b->pendingIrqsHigh=0;a->interruptMode2=b->interruptMode2=false;a->history();b->lastRead=b->lastWrite=-1;irq.setMask(kstation::ControllerInterruptRuntime::Mask::Disabled);auto put=[&](unsigned p,uint8_t val){a->memory[p]=b->memory[p]=val;};unsigned first=(flags&2)?253:0;unsigned count=kind?5:2;put(0xfffd2c,0);put(0xfffd2d,uint8_t(first+count));put(0xfffd2e,0);put(0xfffd2f,uint8_t(first));put(0xfffe30,0);for(unsigned i=0;i<count;++i)put(0xfffd30+((first+i)&255),uint8_t((v+i*23)&127));a->pc=a->makepc(kind?0x11ca:0x11b8);check(wait.start(kind?kstation::ControllerFirmwareNumberRuntime::Kind::Long:kstation::ControllerFirmwareNumberRuntime::Kind::Word),"start");while(wait.active()){x.n=y.n=0;auto c=wait.nextClocks(*b,irq);check(c,"no phase");if(phases%251==0)for(unsigned budget=0;budget<c;++budget){auto old=b->cycles;auto z=wait.advanceBefore(*b,irq,budget);check(!z.clocks&&old==b->cycles&&!y.n,"short");++shorts;}auto at=a->getPC();auto z=wait.advanceBefore(*b,irq,c);check(z.clocks==c,"advance");a->step();if(a->cycles!=b->cycles||x.n!=y.n){std::fprintf(stderr,"pc%x cycle%llu/%llu io%u/%u\n",at,a->cycles,b->cycles,x.n,y.n);throw std::runtime_error("phase");}for(unsigned i=0;i<x.n;++i)check(x.e[i].time==y.e[i].time&&x.e[i].addr==y.e[i].addr&&x.e[i].value==y.e[i].value&&x.e[i].write==y.e[i].write,"io");++phases;events+=x.n;check(phases<10000000,"hang");}check(a->getPC()==0x50000&&(kind?uint32_t(a->reg32(1))==wait.value():uint16_t(a->reg16(1))==wait.value()),"result");++cases;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"io\":%llu,\"shorts\":%llu}\n",cases,phases,events,shorts);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
